pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(name) = bytes.strip_prefix("v:2|hello|") {
        return Ok(Msg::Hello(name.into()));
    }
    if let Some(sequence) = bytes.strip_prefix("v:2|heartbeat|") {
        return sequence
            .parse::<u32>()
            .map(Msg::Heartbeat)
            .map_err(|_| "invalid heartbeat sequence".into());
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(name) => format!("v:2|hello|{}", name),
        Msg::Heartbeat(sequence) => format!("v:2|heartbeat|{}", sequence),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn decodes_ping_frame_successfully() {
        let msg = decode("ping").expect("ping frame should decode");
        assert!(matches!(msg, Msg::Ping));
    }

    #[test]
    fn hello_uses_v2_envelope() {
        let encoded = encode(&Msg::Hello("Ada".into()));
        assert_eq!(encoded, "v:2|hello|Ada");
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(name)) if name == "Ada"));
    }

    #[test]
    fn heartbeat_carries_sequence_number() {
        let encoded = encode(&Msg::Heartbeat(42));
        assert_eq!(encoded, "v:2|heartbeat|42");
        assert!(matches!(decode(&encoded), Ok(Msg::Heartbeat(42))));
    }
}
